-- Fictional watch identifiers only. Run on the owned local synthetic database.
begin;
do $$
declare actor uuid:=ar_private.access_owner();c uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();j uuid;j2 uuid;g text;r jsonb;before_revision bigint;begin
 insert into ar_private.tracker_bindings(region,owner,file_id,enabled,bootstrap_confirmed) values('phuket',actor,'synthetic_notifications_file_12345',true,true)
 on conflict(region) do update set owner=excluded.owner,file_id=excluded.file_id,enabled=true,bootstrap_confirmed=true;
 delete from ar_private.tracker_wakes where region='phuket';delete from ar_private.tracker_watch_channels where region='phuket';
 if public.ar_tracker_watch_prepare('phuket',c,repeat('a',64))->>'status'<>'prepared' then raise exception 'prepare';end if;
 if public.ar_tracker_watch_prepare('phuket',c2,repeat('b',64))->>'status'<>'busy' then raise exception 'concurrent registration';end if;
 if public.ar_tracker_watch_notify(c,repeat('b',64),'fictional-resource','1','sync')->>'status'<>'invalid' then raise exception 'wrong token';end if;
 if public.ar_tracker_watch_notify(c,repeat('a',64),'unverified-early-resource','1','sync')->>'status'<>'accepted' then raise exception 'early sync';end if;
 if exists(select 1 from ar_private.tracker_wakes where region='phuket') or exists(select 1 from ar_private.tracker_watch_channels where channel=c and resource_id is not null) then raise exception 'early sync authorized read';end if;
 r:=public.ar_tracker_watch_activate(c,'fictional-resource',now()+interval '23 hours');j:=(r->>'id')::uuid;
 if j is null then raise exception 'baseline missing';end if;
 if not exists(select 1 from jsonb_array_elements(public.ar_tracker_wake_pending()) x where x->>'id'=j::text) then raise exception 'activation must dispatch immediately';end if;
 select generation::text into g from ar_private.tracker_wakes where id=j;
 if public.ar_tracker_wake_restart(j)->>'status'<>'restarted' or public.ar_tracker_wake_restart(j)->>'status'<>'ignored' or public.ar_tracker_wake_begin(j)->>'status'<>'obsolete' then raise exception 'terminal-before-begin recovery fence';end if;
 select id into j2 from ar_private.tracker_wakes where region='phuket';
 if j2=j or (select generation::text from ar_private.tracker_wakes where id=j2)<>g or not exists(select 1 from jsonb_array_elements(public.ar_tracker_wake_pending()) x where x->>'id'=j2::text) then raise exception 'restart changed generation or delayed';end if;j:=j2;
 if public.ar_tracker_watch_prepare('phuket',c2,repeat('b',64))->>'status'<>'current' then raise exception 'healthy channel renewed';end if;
 if public.ar_tracker_watch_notify(c,repeat('a',64),'wrong-resource','2','update')->>'status'<>'invalid' then raise exception 'resource spoof';end if;
 if public.ar_tracker_watch_notify(c,repeat('a',64),'fictional-resource','2','trash')->>'status'<>'ignored' then raise exception 'unsupported state';end if;
 if public.ar_tracker_watch_notify(c,repeat('a',64),'fictional-resource','18446744073709551616','update')->>'status'<>'invalid' then raise exception 'uint64 overflow';end if;
 r:=public.ar_tracker_watch_notify(c,repeat('a',64),'fictional-resource','18446744073709551615','update');
 if r->>'status'<>'accepted' or (r->>'id')::uuid<>j then raise exception 'burst not coalesced';end if;
 if public.ar_tracker_watch_notify(c,repeat('a',64),'fictional-resource','18446744073709551615','update')->>'status'<>'ignored' or public.ar_tracker_watch_notify(c,repeat('a',64),'fictional-resource','3','change')->>'status'<>'ignored' then raise exception 'message dedup';end if;
 update ar_private.tracker_watch_channels set expires_at=now()+interval '1 hour' where channel=c;
 if public.ar_tracker_watch_prepare('phuket',c2,repeat('b',64))->>'status'<>'prepared' then raise exception 'renewal';end if;
 perform public.ar_tracker_watch_activate(c2,'fictional-resource-2',now()+interval '23 hours');
 if not exists(select 1 from ar_private.tracker_watch_channels where channel=c and state='active') then raise exception 'renewal lost old channel';end if;
 update ar_private.tracker_wakes set due_at=now()-interval '1 second' where id=j;
 if not exists(select 1 from jsonb_array_elements(public.ar_tracker_wake_pending()) x where x->>'id'=j::text) then raise exception 'pending absent';end if;
 r:=public.ar_tracker_wake_begin(j);g:=r->>'generation';
 if r->>'status'<>'ready' or public.ar_tracker_wake_begin(j)->>'generation'<>g then raise exception 'begin retry drift';end if;
 if public.ar_tracker_wake_restart(j)->>'status'<>'ignored' then raise exception 'restart replaced running workflow';end if;
 perform public.ar_tracker_watch_notify(c2,repeat('b',64),'fictional-resource-2','2','change');
 if public.ar_tracker_wake_finish(j,g,true)->>'status'<>'finished' then raise exception 'finish';end if;
 select id into j2 from ar_private.tracker_wakes where region='phuket';
 if j2=j or public.ar_tracker_wake_finish(j,g,true)->>'status'<>'obsolete' then raise exception 'stale acknowledgement';end if;
 update ar_private.tracker_wakes set due_at=now()-interval '1 second' where id=j2;
 r:=public.ar_tracker_wake_begin(j2);if (public.ar_tracker_wake_finish(j2,r->>'generation',false)->>'retryAfterSeconds')::int<>30 then raise exception 'workflow retry delay';end if;
 if exists(select 1 from ar_private.tracker_wakes where id=j2) or not exists(select 1 from ar_private.tracker_wakes where region='phuket' and generation>consumed and due_at between now()+interval '29 seconds' and now()+interval '31 seconds') then raise exception 'retry work lost/backoff';end if;
 update ar_private.tracker_wakes set due_at=now()-interval '1 second' where region='phuket';select id into j from ar_private.tracker_wakes where region='phuket';r:=public.ar_tracker_wake_begin(j);
 update ar_private.tracker_wakes set running_until=now()-interval '1 second' where id=j;
 perform public.ar_tracker_wake_pending();if public.ar_tracker_wake_finish(j,r->>'generation',true)->>'status'<>'obsolete' then raise exception 'crashed identity not fenced';end if;
 select id into j from ar_private.tracker_wakes where region='phuket';r:=public.ar_tracker_wake_begin(j);
 if public.ar_tracker_wake_finish(j,r->>'generation',true)->>'retryAfterSeconds'<>'0' then raise exception 'successful delay';end if;
 if public.ar_tracker_wake_restart(j)->>'status'<>'ignored' then raise exception 'restart revived consumed workflow';end if;
 perform public.ar_tracker_watch_notify(c2,repeat('b',64),'fictional-resource-2','3','change');
 if not exists(select 1 from jsonb_array_elements(public.ar_tracker_wake_pending()) x where x->>'id'<>j::text and x->>'region'='phuket') then raise exception 'completed workflow UUID reused or delayed callback';end if;
 update ar_private.tracker_watch_channels set expires_at=now()-interval '1 second' where channel=c2;
 if public.ar_tracker_watch_notify(c2,repeat('b',64),'fictional-resource-2','4','change')->>'status'<>'invalid' then raise exception 'expired channel';end if;
 update ar_private.tracker_bindings set enabled=false where region='phuket';
 select id into j from ar_private.tracker_wakes where region='phuket';if public.ar_tracker_wake_restart(j)->>'status'<>'ignored' then raise exception 'restart ignored disabled binding';end if;
 if public.ar_tracker_watch_notify(c,repeat('a',64),'fictional-resource','18446744073709551615','update')->>'status'<>'invalid' or public.ar_tracker_watch_prepare('phuket',gen_random_uuid(),repeat('c',64))->>'status'<>'disabled' or jsonb_array_length(public.ar_tracker_wake_pending())<>0 then raise exception 'disabled binding authorized work';end if;
 update ar_private.tracker_bindings set enabled=true where region='phuket';
 insert into ar_private.tracker_data_revisions(region,revision) values('phuket',700) on conflict(region) do update set revision=700;
 update ar_private.tracker_bindings set last_success_at=now()-interval '1 second' where region='phuket';
 if not exists(select 1 from public.ar_tracker_publications where region='phuket' and revision=700) then raise exception 'publication missing';end if;
 update public.ar_tracker_publications set published_at=now()-interval '1 day' where region='phuket';
 update ar_private.tracker_bindings set last_success_at=now() where region='phuket';
 if (select published_at from public.ar_tracker_publications where region='phuket')<>now()-interval '1 day' then raise exception 'unchanged revision republished';end if;
 if has_function_privilege('authenticated','public.ar_tracker_watch_notify(uuid,text,text,text,text)','execute') or has_table_privilege('authenticated','ar_private.tracker_wakes','select') or has_table_privilege('authenticated','public.ar_tracker_publications','insert') or not has_table_privilege('authenticated','public.ar_tracker_publications','select') then raise exception 'privilege boundary';end if;
 if has_function_privilege('authenticated','public.ar_tracker_wake_restart(uuid)','execute') or has_function_privilege('anon','public.ar_tracker_wake_restart(uuid)','execute') or not has_function_privilege('service_role','public.ar_tracker_wake_restart(uuid)','execute') then raise exception 'restart privilege boundary';end if;
 if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='ar_tracker_publications') then raise exception 'realtime publication not registered';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);if not ar_private.tracker_publication_visible('phuket') then raise exception 'authorized publication';end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);if ar_private.tracker_publication_visible('phuket') then raise exception 'unauthorized publication';end if;
end $$;
do $$
declare regional uuid:=gen_random_uuid();n integer;begin
 insert into ar_private.access_members(email,regions,auth_user_id) values('watch-regional@example.test',array['khao-lak'],regional);
 insert into auth.users(id,email,email_confirmed_at) values(regional,'watch-regional@example.test',now());
 insert into public.ar_tracker_publications(region,revision) values('khao-lak',701) on conflict(region) do update set revision=701;
 perform set_config('request.jwt.claim.sub',regional::text,true);
 execute 'set local role authenticated';
 select count(*) into n from public.ar_tracker_publications;
 if n<>1 or exists(select 1 from public.ar_tracker_publications where region='phuket') then raise exception 'regional realtime RLS leaked';end if;
 execute 'reset role';
 update ar_private.access_members set active=false where auth_user_id=regional;
 execute 'set local role authenticated';
 if exists(select 1 from public.ar_tracker_publications) then raise exception 'disabled member realtime RLS leaked';end if;
 execute 'reset role';
end $$;
rollback;
